{
    "fields": [
        {
            "id": "titulo",
            "type": "text",
            "label": "Título do episódio",
            "description": "Título completo exibido no topo da página.",
            "mandatory": false
        },
        {
            "id": "selo",
            "type": "text",
            "label": "Número do episódio",
            "description": "Número com dois dígitos (ex.: 01).",
            "mandatory": false
        },
        {
            "id": "status",
            "type": "text",
            "label": "Status",
            "description": "Disponível ou Em breve.",
            "mandatory": false
        },
        {
            "id": "status_chave",
            "type": "text",
            "label": "Chave visual do status",
            "description": "on (disponível) ou soon (em breve).",
            "mandatory": false
        },
        {
            "id": "colecao",
            "type": "text",
            "label": "Coleção",
            "description": "Nome da listagem de retorno (Episódios).",
            "mandatory": false
        },
        {
            "id": "colecao_url",
            "type": "text",
            "label": "Caminho da coleção",
            "description": "Caminho relativo da listagem (episodios\/).",
            "mandatory": false
        },
        {
            "id": "categoria",
            "type": "text",
            "label": "Trilha \/ tag",
            "description": "Trilha temática do episódio.",
            "mandatory": false
        },
        {
            "id": "relacionado",
            "type": "text",
            "label": "Estágio da série",
            "description": "Estágio curricular a que o episódio pertence.",
            "mandatory": false
        },
        {
            "id": "resumo",
            "type": "textarea",
            "label": "Resumo",
            "description": "Resumo curto usado nos cards e no cabeçalho.",
            "mandatory": false
        },
        {
            "id": "link_principal",
            "type": "text",
            "label": "URL do YouTube \/ Playlist",
            "description": "Sempre a playlist oficial da série.",
            "mandatory": false
        },
        {
            "id": "link_principal_rotulo",
            "type": "text",
            "label": "Rótulo do link do YouTube",
            "description": "Texto do botão principal.",
            "mandatory": false
        },
        {
            "id": "link_secundario",
            "type": "text",
            "label": "URL dos materiais no GitHub",
            "description": "Repositório oficial de materiais.",
            "mandatory": false
        },
        {
            "id": "link_secundario_rotulo",
            "type": "text",
            "label": "Rótulo do link de materiais",
            "description": "Texto do botão secundário.",
            "mandatory": false
        },
        {
            "id": "topicos",
            "type": "html",
            "label": "Tópicos principais",
            "description": "Itens <li> com os tópicos do episódio.",
            "mandatory": false
        },
        {
            "id": "conteudo",
            "type": "html",
            "label": "Conteúdo completo",
            "description": "Corpo editorial do episódio.",
            "mandatory": false
        }
    ],
    "template_map": [
